#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <fcntl.h>

#define MAX_SESSIONS 256
#define MAX_CACHE_ENTRIES 64
#define TOKEN_EXPIRY_SECS 3600
#define LISTEN_PORT 8080
#define MAX_REQUEST_SIZE 4096

typedef struct {
    uint64_t token;
    int user_id;
    int role;  // 0=user, 1=admin
    time_t created;
    int active;
} session_t;

typedef struct {
    uint32_t token_key;  // cache key derived from token
    int session_idx;
    time_t cached_at;
    int valid;
} cache_entry_t;

static session_t sessions[MAX_SESSIONS];
static cache_entry_t token_cache[MAX_CACHE_ENTRIES];
static pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Generate cryptographically random token
static uint64_t generate_token(void) {
    uint64_t token;
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return 0;
    if (read(fd, &token, sizeof(token)) != sizeof(token)) {
        close(fd);
        return 0;
    }
    close(fd);
    return token;
}

// Create a new session
static int create_session(int user_id, int role, uint64_t *out_token) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!sessions[i].active) {
            sessions[i].token = generate_token();
            sessions[i].user_id = user_id;
            sessions[i].role = role;
            sessions[i].created = time(NULL);
            sessions[i].active = 1;
            *out_token = sessions[i].token;
            pthread_mutex_unlock(&session_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return -1;
}

// Compute cache index from token
static inline uint32_t cache_key(uint64_t token) {
    // Use lower 32 bits XORed with upper 32 bits for distribution
    return (uint32_t)(token & 0xFFFFFFFF) ^ (uint32_t)(token >> 32);
}

// Cache slot index
static inline int cache_slot(uint32_t key) {
    return key % MAX_CACHE_ENTRIES;
}

// Lookup session in cache (fast path)
// Returns session index or -1 if not cached
static int cache_lookup(uint64_t token) {
    uint32_t key = cache_key(token);
    int slot = cache_slot(key);

    pthread_mutex_lock(&cache_lock);
    cache_entry_t *entry = &token_cache[slot];
    if (entry->valid && entry->token_key == key) {
        // Cache hit - verify not expired
        if (time(NULL) - entry->cached_at < 30) {
            int idx = entry->session_idx;
            pthread_mutex_unlock(&cache_lock);
            return idx;
        }
        // Cache entry expired, invalidate
        entry->valid = 0;
    }
    pthread_mutex_unlock(&cache_lock);
    return -1;
}

// Update cache with session lookup result
static void cache_update(uint64_t token, int session_idx) {
    uint32_t key = cache_key(token);
    int slot = cache_slot(key);

    pthread_mutex_lock(&cache_lock);
    token_cache[slot].token_key = key;
    token_cache[slot].session_idx = session_idx;
    token_cache[slot].cached_at = time(NULL);
    token_cache[slot].valid = 1;
    pthread_mutex_unlock(&cache_lock);
}

// Full session validation (slow path)
static int validate_session_full(uint64_t token) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].active && sessions[i].token == token) {
            if (time(NULL) - sessions[i].created > TOKEN_EXPIRY_SECS) {
                sessions[i].active = 0;
                pthread_mutex_unlock(&session_lock);
                return -1;
            }
            pthread_mutex_unlock(&session_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return -1;
}

// Main authentication check - uses cache for performance
static int authenticate_request(uint64_t token) {
    // Fast path: check cache first
    int idx = cache_lookup(token);
    if (idx >= 0) {
        // Cache hit - return cached session index
        // The cache stores validated session indices
        return idx;
    }

    // Slow path: full validation
    idx = validate_session_full(token);
    if (idx >= 0) {
        // Cache the result for future lookups
        cache_update(token, idx);
    }
    return idx;
}

// Check if session has admin role
static int is_admin(int session_idx) {
    if (session_idx < 0 || session_idx >= MAX_SESSIONS) return 0;
    return sessions[session_idx].role == 1;
}

// Parse token from request header
static uint64_t parse_token(const char *request) {
    const char *auth = strstr(request, "Authorization: Bearer ");
    if (!auth) return 0;
    auth += strlen("Authorization: Bearer ");
    char token_str[20];
    int i = 0;
    while (auth[i] && auth[i] != '\r' && auth[i] != '\n' && i < 19) {
        token_str[i] = auth[i];
        i++;
    }
    token_str[i] = '\0';
    return strtoull(token_str, NULL, 16);
}

// Handle admin endpoint
static void handle_admin(int client_fd, int session_idx) {
    if (!is_admin(session_idx)) {
        const char *resp = "HTTP/1.1 403 Forbidden\r\nContent-Length: 6\r\n\r\nDenied";
        write(client_fd, resp, strlen(resp));
        return;
    }
    // Admin action: return sensitive system info
    char buf[512];
    FILE *f = fopen("/etc/hostname", "r");
    if (f) {
        size_t n = fread(buf, 1, sizeof(buf)-1, f);
        buf[n] = '\0';
        fclose(f);
    } else {
        strcpy(buf, "unknown");
    }
    char response[1024];
    int len = snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: %zu\r\n\r\n%s",
        strlen(buf), buf);
    write(client_fd, response, len);
}

// Handle login endpoint
static void handle_login(int client_fd, const char *request) {
    // Simple hardcoded users for demonstration
    const char *body = strstr(request, "\r\n\r\n");
    if (!body) return;
    body += 4;

    int user_id = -1;
    int role = 0;

    if (strstr(body, "admin:secretpass")) {
        user_id = 0;
        role = 1;
    } else if (strstr(body, "user:userpass")) {
        user_id = 1;
        role = 0;
    }

    if (user_id < 0) {
        const char *resp = "HTTP/1.1 401 Unauthorized\r\nContent-Length: 11\r\n\r\nBad credentials";
        write(client_fd, resp, strlen(resp));
        return;
    }

    uint64_t token;
    int idx = create_session(user_id, role, &token);
    if (idx < 0) {
        const char *resp = "HTTP/1.1 503 Service Unavailable\r\nContent-Length: 4\r\n\r\nFull";
        write(client_fd, resp, strlen(resp));
        return;
    }

    char response[256];
    int len = snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 16\r\n\r\n%016llx",
        (unsigned long long)token);
    write(client_fd, response, len);
}

// Handle client connection
static void *handle_client(void *arg) {
    int client_fd = *(int*)arg;
    free(arg);

    char request[MAX_REQUEST_SIZE];
    ssize_t n = read(client_fd, request, sizeof(request) - 1);
    if (n <= 0) {
        close(client_fd);
        return NULL;
    }
    request[n] = '\0';

    if (strncmp(request, "POST /login", 11) == 0) {
        handle_login(client_fd, request);
    } else if (strncmp(request, "GET /admin", 10) == 0) {
        uint64_t token = parse_token(request);
        if (token == 0) {
            const char *resp = "HTTP/1.1 401 Unauthorized\r\nContent-Length: 8\r\n\r\nNo token";
            write(client_fd, resp, strlen(resp));
        } else {
            int session_idx = authenticate_request(token);
            if (session_idx < 0) {
                const char *resp = "HTTP/1.1 401 Unauthorized\r\nContent-Length: 7\r\n\r\nInvalid";
                write(client_fd, resp, strlen(resp));
            } else {
                handle_admin(client_fd, session_idx);
            }
        }
    } else {
        const char *resp = "HTTP/1.1 404 Not Found\r\nContent-Length: 9\r\n\r\nNot found";
        write(client_fd, resp, strlen(resp));
    }

    close(client_fd);
    return NULL;
}

int main(void) {
    memset(sessions, 0, sizeof(sessions));
    memset(token_cache, 0, sizeof(token_cache));

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(LISTEN_PORT);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) return 1;
    if (listen(server_fd, 32) < 0) return 1;

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int *client_fd = malloc(sizeof(int));
        if (!client_fd) continue;
        *client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (*client_fd < 0) { free(client_fd); continue; }

        pthread_t tid;
        if (pthread_create(&tid, NULL, handle_client, client_fd) != 0) {
            close(*client_fd);
            free(client_fd);
        } else {
            pthread_detach(tid);
        }
    }

    return 0;
}
